const dsl = `workspace "Parcel Tracker" "A parcel delivery tracking platform" {

    !identifiers hierarchical

    model {

        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company" {

            webPortal = container "Web Portal" "Where customers look up the status of their shipments" "Web application" {
                pricingRules = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Shared library"
            }

            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service" {
                pricingRules = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Shared library"
            }

            database = container "Database" "Stores shipment and dispatch records" "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization" "External"

        customer -> parcelTracker.webPortal "looks up the status of their shipments" "HTTPS"
        parcelTracker.webPortal -> parcelTracker.database "reads shipment records from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "writes dispatch records to" "SQL"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "HTTPS"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        component parcelTracker.webPortal "WebPortalComponents" {
            include *
            autoLayout
            title "Components of Web Portal"
        }

        component parcelTracker.dispatchService "DispatchServiceComponents" {
            include *
            autoLayout
            title "Components of Dispatch Service"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}`;

const [parse, validate, inspect] = await Promise.allSettled([
  tools.structurizr.parse({ dsl }),
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);

const fmt = (r) => r.status === "fulfilled" ? JSON.stringify(r.value, null, 2) : `REJECTED: ${r.reason}`;
return { parse: fmt(parse), validate: fmt(validate), inspect: fmt(inspect) };

